use vstd::prelude::*;

verus! {
    fn extract_rear_chars(l: &Vec<Vec<char>>) -> (r: Vec<char>)
        requires
            forall(|i: nat| i < l.len() ==> l[i].len() > 0), // Each inner vector is non-empty
        ensures
            r.len() == l.len(), // Output length equals number of inner vectors
            forall(|i: nat| i < l.len() ==> r[i] == l[i][l[i].len() - 1]), // r[i] is the last character of l[i]
    {
        let mut r: Vec<char> = Vec::new();
        let mut idx: usize = 0;

        while idx < l.len()
            invariant
                idx <= l.len(), // idx is within bounds
                r.len() == idx, // r has the correct number of elements
                forall(|i: nat| i < idx ==> r[i] == l[i][l[i].len() - 1]), // r[i] is the last character of l[i]
            decreases l.len() - idx, // Decreases clause for termination
        {
            // Push the last character of the current inner vector to r
            r.push(l[idx][l[idx].len() - 1]);
            idx = idx + 1; // Move to the next inner vector
        }
        r
    }
}

